def count_remaining_robot_sets(N, robot_data):
    from collections import defaultdict
    from itertools import combinations
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    robot_data = []

    index = 1
    for _ in range(N):
        X_i = int(data[index])
        D_i = int(data[index + 1])
        robot_data.append((X_i, D_i))
        index += 2

    robot_data.sort()

    def activate_robots(active_robots):
        activated = set()
        for robot in active_robots:
            X_i, D_i = robot_data[robot]
            for j in range(N):
                if j != robot and j not in activated:
                    X_j, D_j = robot_data[j]
                    if X_i <= X_j < X_i + D_i:
                        activated.add(j)
        return active_robots.union(activated)

    result_set = set()

    for mask in range(1 << N):
        active_robots = {i for i in range(N) if mask & (1 << i)}
        activated_set = activate_robots(active_robots)

        remaining_set = frozenset(range(N)) - activated_set
        result_set.add(remaining_set)

    return len(result_set) % MOD

